package coreJava;

public class forLoopExample {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		
		// for loop from 1 to 10
		
		for (int i = 1; i < 11; i++) 
		{
			System.out.println(i);
		}
		
		// for loop from 0 to 99
		
		for (int i = 0; i < 100; i+=2) 
		{
			System.out.println(i);
		}

	}

}
